import { readFile } from "node:fs/promises";

import { USERS, expect, sample, test, uniqueName } from "../../fixtures";

test("audit events are listed oldest first with actor and action", { tag: "@AUD-01" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const name = uniqueName("Audit Vendor");
  const createRes = await member.post("/api/vendors", {
    data: { name, category: "software", contact_email: `audit.${Date.now().toString(36)}@supplier-audit.com` },
  });
  const createBody = await createRes.text();
  expect(createRes.status(), createBody).toBe(201);
  const vendor = JSON.parse(createBody) as { id: string };

  const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: {
        name: "w9.txt",
        mimeType: "text/plain",
        buffer: await readFile(sample("w9.txt")),
      },
    },
  });
  const uploadBody = await uploadRes.text();
  expect(uploadRes.status(), uploadBody).toBe(201);

  // Act: extraction runs in the background, so poll until its event is recorded.
  let lastBody = "";
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/audit`);
        lastBody = await res.text();
        if (res.status() !== 200) return `status ${res.status()}`;
        const items = (JSON.parse(lastBody) as { items: { action: string }[] }).items;
        return items.map((e) => e.action).join(",");
      },
      { message: `audit trail never reached document.extracted; last response: ${lastBody}`, timeout: 30_000 },
    )
    .toContain("document.extracted");

  const auditRes = await member.get(`/api/vendors/${vendor.id}/audit`);
  const auditBody = await auditRes.text();

  // Assert
  expect(auditRes.status(), auditBody).toBe(200);
  const { items } = JSON.parse(auditBody) as {
    items: { action: string; at: string; actor: { id: string; name: string; email: string } }[];
  };
  expect(items.map((e) => e.action), auditBody).toEqual([
    "vendor.created",
    "document.uploaded",
    "document.extracted",
  ]);
  for (const event of items) {
    expect(event.actor.email, auditBody).toBe(USERS.member);
    expect(event.actor.name, auditBody).toBeTruthy();
    expect(Number.isNaN(Date.parse(event.at)), auditBody).toBe(false);
  }
  const times = items.map((e) => Date.parse(e.at));
  expect([...times].sort((a, b) => a - b), auditBody).toEqual(times);
});
